#!/usr/bin/env node
/**
 * P0-2 SHP node: independent HTTPS origin, signed node descriptor, static world,
 * one-time short-lived arrive tokens (bound to target world + session + nonce).
 *
 * Usage:
 *   node scripts/serve-node.mjs --name alice --port 8443 --peer https://hana.example:8444 --client-dist apps/playground/dist
 *
 * Test-only TLS: certificates under .p0-tls/ are generated by scripts/tls-fixture.mjs.
 */
import { createServer } from "node:https";
import { readFileSync, existsSync, statSync, createReadStream } from "node:fs";
import { createPublicKey, randomBytes, sign } from "node:crypto";
import { extname, join, normalize, resolve } from "node:path";
import { canonicalize } from "../packages/check/src/jcs.mjs";

const ROOT = resolve(new URL("..", import.meta.url).pathname);
const TLS = join(ROOT, ".p0-tls");
const args = process.argv.slice(2);
const arg = (k, d) => {
  const i = args.indexOf(`--${k}`);
  return i >= 0 ? args[i + 1] : d;
};
const NAME = arg("name", "alice");
const PORT = Number(arg("port", NAME === "alice" ? 8443 : 8444));
const ORIGIN = arg("origin", `https://${NAME}.example:${PORT}`);
const PEER = arg("peer", NAME === "alice" ? "https://hana.example:8444" : "https://alice.example:8443");
const CLIENT_DIST = arg("client-dist", null);
const TOKEN_TTL_MS = Number(process.env.P0_TOKEN_TTL_MS || 5000);
const RATE_LIMIT = Number(process.env.P0_RATE_LIMIT || 60); // requests per 10s per client IP
const ROOM_FULL = args.includes("--room-full");
const PRIVATE = args.includes("--private");

const worldId = NAME === "alice" ? "pixel-rooftop" : "neon-alley";
const worldPath = join(ROOT, "worlds", worldId, "world.json");
const raw = JSON.parse(readFileSync(worldPath, "utf8"));
const ORIGINS = [
  ["https://alice.example", "https://alice.example:8443"],
  ["https://hana.example", "https://hana.example:8444"],
];
const live = JSON.parse(JSON.stringify(raw));
for (const [from, to] of ORIGINS) {
  live.id = live.id.replace(from, to);
  for (const p of live.portals || []) p.target.url = p.target.url.replace(from, to);
  if (live.author?.url) live.author.url = live.author.url.replace(from, to);
}
live.id = live.id.replace(/^https:\/\/(alice|hana)\.example:844[34]/, NAME === "alice" ? "https://alice.example:8443" : "https://hana.example:8444");

const nodeKey = JSON.parse(readFileSync(join(TLS, "nodes", `${NAME}.json`), "utf8"));
const privateKey = nodeKey.privatePem;
const publicJwk = nodeKey.publicJwk;

function descriptor() {
  const doc = {
    protocol: { name: "SHP", version: "0.1" },
    node: { id: `did:web:${NAME}.example`, origin: ORIGIN, publicKey: publicJwk },
    capabilities: { arrive: true, trustAnchors: true, maxPlayers: 20, roomFull: ROOM_FULL, private: PRIVATE },
    worlds: [{ id: live.id, url: live.id, title: live.title }],
  };
  const value = sign(null, Buffer.from(canonicalize(doc)), privateKey).toString("base64url");
  return { ...doc, signature: { alg: "ed25519", keyId: `did:web:${NAME}.example`, canonicalization: "RFC8785-JCS", value } };
}

const issuedNonces = new Map(); // nonce -> exp
const tokens = new Map(); // token -> {world, session, nonce, exp, used}
const cleanup = setInterval(() => {
  const now = Date.now();
  for (const [k, v] of issuedNonces) if (v < now) issuedNonces.delete(k);
  for (const [k, v] of tokens) if (v.exp < now - 60_000) tokens.delete(k);
}, 30_000);
cleanup.unref?.();

const CORS = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Methods": "GET,POST,OPTIONS",
  "Access-Control-Allow-Headers": "content-type",
};
const rateBuckets = new Map();
function rateLimited(ip) {
  const now = Date.now();
  let b = rateBuckets.get(ip);
  if (!b || now - b.start > 10_000) { b = { start: now, count: 0 }; rateBuckets.set(ip, b); }
  b.count += 1;
  return b.count > RATE_LIMIT;
}
function clientIp(req) {
  return req.socket?.remoteAddress || "unknown";
}

function send(res, code, body, headers = {}) {
  res.writeHead(code, { ...CORS, "Cache-Control": "no-store", ...headers });
  if (typeof body === "string" || Buffer.isBuffer(body)) res.end(body);
  else if (body !== undefined) res.end(JSON.stringify(body));
  else res.end();
}
function sendJson(res, code, body) {
  send(res, code, JSON.stringify(body), { "Content-Type": "application/json; charset=utf-8" });
}
async function readJson(req, limit = 16 * 1024) {
  const chunks = [];
  let size = 0;
  for await (const c of req) {
    size += c.length;
    if (size > limit) throw Object.assign(new Error("body too large"), { status: 413 });
    chunks.push(c);
  }
  try {
    return JSON.parse(Buffer.concat(chunks).toString("utf8") || "{}");
  } catch {
    throw Object.assign(new Error("invalid json"), { status: 400 });
  }
}

const MIME = { ".html": "text/html; charset=utf-8", ".js": "text/javascript", ".css": "text/css", ".json": "application/json", ".glb": "model/gltf-binary", ".png": "image/png", ".svg": "image/svg+xml", ".map": "application/json" };

function serveFile(res, file, fallback404 = true) {
  if (!existsSync(file) || !statSync(file).isFile()) {
    if (fallback404) return sendJson(res, 404, { error: "not found" });
    return false;
  }
  res.writeHead(200, { ...CORS, "Content-Type": MIME[extname(file)] || "application/octet-stream", "Cache-Control": "no-store" });
  createReadStream(file).pipe(res);
  return true;
}

const server = createServer(
  {
    key: readFileSync(join(TLS, `${NAME}.key`)),
    cert: readFileSync(join(TLS, `${NAME}.crt`)),
  },
  async (req, res) => {
    const url = new URL(req.url, ORIGIN);
    try {
      if (req.method === "OPTIONS") return send(res, 204);
      if (url.pathname === "/healthz") {
        return sendJson(res, 200, { ok: true, name: NAME, origin: ORIGIN, pid: process.pid, tokenTtlMs: TOKEN_TTL_MS });
      }
      if (url.pathname === "/.well-known/weave-node.json") {
        return sendJson(res, 200, descriptor());
      }
      if (url.pathname === "/p0/trust.json") {
        const trust = join(TLS, "trust.json");
        if (!existsSync(trust)) return sendJson(res, 404, { error: "trust fixture missing" });
        return send(res, 200, readFileSync(trust), { "Content-Type": "application/json" });
      }
      if (url.pathname === "/arrive" && req.method === "POST") {
        if (rateLimited(clientIp(req))) return sendJson(res, 429, { error: "E_RATE_LIMITED", retryAfterSec: 10 });
        const body = await readJson(req);
        if (PRIVATE) return sendJson(res, 404, { error: "E_NOT_FOUND" });
        if (ROOM_FULL) return sendJson(res, 409, { error: "E_ROOM_FULL" });
        if (body.targetWorld !== live.id) return sendJson(res, 400, { error: "E_WRONG_WORLD" });
        if (!/^[A-Za-z0-9_-]{8,64}$/.test(body.sessionId || "")) return sendJson(res, 400, { error: "E_BAD_SESSION" });
        if (!/^[A-Za-z0-9_-]{16,64}$/.test(body.nonce || "")) return sendJson(res, 400, { error: "E_BAD_NONCE" });
        const now = Date.now();
        if (issuedNonces.has(body.nonce)) return sendJson(res, 409, { error: "E_NONCE_REPLAY" });
        issuedNonces.set(body.nonce, now + 10 * 60_000);
        const token = randomBytes(24).toString("base64url");
        const exp = now + TOKEN_TTL_MS;
        tokens.set(token, { world: live.id, session: body.sessionId, nonce: body.nonce, exp, used: false });
        return sendJson(res, 200, { token, expiresAt: exp, world: live.id, sessionId: body.sessionId, node: ORIGIN });
      }
      if (url.pathname === "/arrive/consume" && req.method === "POST") {
        if (rateLimited(clientIp(req))) return sendJson(res, 429, { error: "E_RATE_LIMITED", retryAfterSec: 10 });
        const body = await readJson(req);
        const rec = tokens.get(body.token);
        if (!rec) return sendJson(res, 404, { error: "E_TOKEN_UNKNOWN" });
        if (rec.used) return sendJson(res, 409, { error: "E_TOKEN_REPLAY" });
        if (Date.now() > rec.exp) return sendJson(res, 410, { error: "E_TOKEN_EXPIRED" });
        rec.used = true;
        return sendJson(res, 200, { ok: true, world: rec.world, sessionId: rec.session });
      }
      // world assets: only this node's world
      if (url.pathname === `/worlds/${worldId}/world.json`) {
        return sendJson(res, 200, live);
      }
      if (url.pathname.startsWith(`/worlds/${worldId}/`)) {
        const rel = decodeURIComponent(url.pathname.slice(`/worlds/${worldId}/`.length));
        const file = normalize(join(ROOT, "worlds", worldId, rel));
        if (!file.startsWith(join(ROOT, "worlds", worldId) + "/")) return sendJson(res, 403, { error: "forbidden" });
        return serveFile(res, file);
      }
      if (CLIENT_DIST) {
        const rel = url.pathname === "/" ? "index.html" : decodeURIComponent(url.pathname).replace(/^\/+/, "");
        const file = normalize(join(CLIENT_DIST, rel));
        if (file.startsWith(CLIENT_DIST + "/") && serveFile(res, file, false)) return;
        return serveFile(res, join(CLIENT_DIST, "index.html"));
      }
      return sendJson(res, 404, { error: "not found" });
    } catch (err) {
      return sendJson(res, err.status || 500, { error: err.message });
    }
  },
);

server.listen(PORT, "127.0.0.1", () => {
  console.log(`[p0-node ${NAME}] ${ORIGIN} -> ${worldId} (peer ${PEER})`);
  console.log(`[p0-node ${NAME}] token ttl ${TOKEN_TTL_MS}ms; rate ${RATE_LIMIT}/10s; roomFull=${ROOM_FULL} private=${PRIVATE}; pid ${process.pid}`);
});
for (const sig of ["SIGINT", "SIGTERM"]) process.on(sig, () => server.close(() => process.exit(0)));
